// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function _run(uint256 v1, uint256 v2, address a) internal {
        try c.SetMinSum(v1) {} catch { return; }
        try c.Initialized() {} catch { return; }
        bool r1;
        bool r2;
        try c.SetMinSum(v2) { r1 = false; } catch { r1 = true; }
        try c.SetLogFile(a) { r2 = false; } catch { r2 = true; }
        assertTrue(r1 && r2 && c.MinSum() == v1);
    }

    function testFuzz_run(uint256 v1, uint256 v2, address a) public {
        vm.assume(a.code.length == 0 && uint160(a) > 0xffff && a != address(this) && a != address(c) && a != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && a != 0x000000000000000000636F6e736F6c652e6c6f67 && a != 0x4e59b44847b379578588920cA78FbF26c0B4956C && a != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(v1, v2, a);
    }

    receive() external payable {}
}
